"""Development helpers: build campaigns, encode KTESTs, run the CLI."""
import base64, json, struct, subprocess, sys

CLI = "/workspace/project/campaign_cli.py"


def run_cli(campaign, expect_error=False):
    data = json.dumps(campaign).encode("utf-8")
    proc = subprocess.run([sys.executable, "-I", "-B", CLI], input=data,
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=200)
    out = proc.stdout.decode("utf-8")
    if proc.returncode != 0:
        raise AssertionError("exit %d: %s" % (proc.returncode, proc.stderr.decode()[:2000]))
    value = json.loads(out)
    if not isinstance(value, dict):
        raise AssertionError("output is not an object")
    return value


def blob(b):
    return struct.pack(">I", len(b)) + b


def encode(objs, version=3, args=(), argv=(0, 0), magic=b"KTEST", extra=b"", object_count=None):
    """objs: list of (name:str, data:bytes)"""
    out = bytearray(magic)
    out += struct.pack(">II", version, len(args))
    for a in args:
        out += blob(a)
    out += struct.pack(">II", argv[0], argv[1])
    out += struct.pack(">I", len(objs) if object_count is None else object_count)
    for name, data in objs:
        out += blob(name.encode("latin-1")) + blob(data)
    out += extra
    return base64.b64encode(bytes(out)).decode("ascii")


def leaf(width, value):
    return int(value).to_bytes(width, "little")


def test_ktest(plan, leaves, **kwargs):
    """Encode one test from plan slots: leaves is a list of ints (one per slot)."""
    slots = plan["slots"]
    objs = []
    if leaves is not None:
        for (name, path, width), value in zip(slots, leaves):
            objs.append((name, leaf(width, value)))
    if plan.get("flag"):
        objs.append((plan["flag"], b"\x00"))
    return encode(objs, **kwargs)


def plan_for(campaign, entry=None):
    out = run_cli(campaign)
    plans = out["plans"]
    if entry is None:
        return out, plans[0]
    for p in plans:
        if p["entry"] == entry:
            return out, p
    raise AssertionError("no plan for " + entry)


def check(name, got, want):
    a = json.dumps(got, sort_keys=True)
    b = json.dumps(want, sort_keys=True)
    if a != b:
        print("FAIL %s\n   got  %s\n   want %s" % (name, a, b))
        return False
    print("pass %s" % name)
    return True
PYEOF
